    oid = order(shop, "c1", ("LAMP", 2)).body["order_id"]
    entry = shop.insights.handle_order_history("c1").body["orders"][0]
    assert entry["total_cents"] == shop.orders.handle_get(oid).body["total_cents"] == 10800

